// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;
import {IToken} from "./IToken.sol";

/// A deliberately broken vault: the analyzer's CI check expects each of its bugs to be found.
contract Vault {
    mapping(address => uint256) public balances;
    IToken public token;

    function deposit() external payable {
        balances[msg.sender] += msg.value;
    }

    // reentrancy-eth: the balance is cleared after the external call.
    function withdraw() external {
        uint256 amount = balances[msg.sender];
        (bool ok, ) = msg.sender.call{value: amount}("");
        require(ok);
        balances[msg.sender] = 0;
    }

    // unchecked-transfer: the token's return value is ignored.
    function pay(address to, uint256 amount) external {
        token.transfer(to, amount);
    }
}

